import {spawn} from 'node:child_process';
import {mkdtemp,rm} from 'node:fs/promises';
import {once} from 'node:events';
import { setTimeout } from 'node:timers/promises';
const root = await mkdtemp(process.cwd()+'/.acceptance-browser-');
const origin = 'http://127.0.0.1:41639';
const chrome = spawn('google-chrome',[
  '--headless','--no-sandbox','--disable-dev-shm-usage','--disable-background-networking',
  '--disable-component-update','--disable-sync','--no-first-run',
  '--proxy-server=http://127.0.0.1:1','--proxy-bypass-list=<-loopback>;127.0.0.1:41639',
  '--remote-debugging-pipe','--user-data-dir='+root,'about:blank'
], {stdio:['ignore','ignore','ignore','pipe','pipe'],env:{...process.env,XDG_CONFIG_HOME:root,XDG_CACHE_HOME:root}});
let id=0, sessionId, input='';
const pending=new Map();
chrome.stdio[4].setEncoding('utf8');
chrome.stdio[4].on('data', chunk=>{
  input+=chunk;
  let end;
  while ((end=input.indexOf('\\0'))>=0) {
    const message=JSON.parse(input.slice(0,end));
    input=input.slice(end+1);
    const waiter=pending.get(message.id);
    if(waiter){ pending.delete(message.id); message.error ? waiter.reject(message.error) : waiter.resolve(message.result); }
  }
});
function cdp(method, params={}, session=sessionId) {
  return new Promise((resolve,reject)=>{
    const key=++id; pending.set(key,{resolve,reject});
    chrome.stdio[3].write(JSON.stringify({id:key,method,params,sessionId:session})+'\\0');
  });
}
async function evaluate(expression) {
  const res=await cdp('Runtime.evaluate',{expression,returnByValue:true});
  if(res.exceptionDetails) throw new Error(JSON.stringify(res.exceptionDetails));
  return res.result.value;
}
async function waitFor(expression) {
  for(let i=0;i<60;i++){
    try { if(await evaluate(expression)) return; } catch {}
    await setTimeout(100);
  }
  throw new Error('Browser timed out: '+expression);
}
try {
  const {targetId}=await cdp('Target.createTarget',{url:'about:blank'});
  ({sessionId}=await cdp('Target.attachToTarget',{targetId,flatten:true}));
  await cdp('Page.enable');
  const nav=await cdp('Page.navigate',{url:origin+'/'});
  if(nav.errorText) throw new Error(nav.errorText);
  await waitFor(\"document.documentElement.getAttribute('data-has-hydrated')==='true'\");
  const anchor=\"Array.from(document.links).find(a=>a.textContent.trim()==='Current shift manual 2.0')\";
  console.log('Home', await evaluate(\"({url:location.href, links:Array.from(document.links).filter(a=>a.textContent.includes('shift manual')).map(a=>[a.textContent,a.getAttribute('href')])})\"));
  await evaluate(anchor+'.click()');
  await waitFor(\"location.pathname "'!== '"'/' && Boolean(document.querySelector('main h1'))\");
  await setTimeout(550);
  const report=\"({url:location.href, lang:document.documentElement.lang, hydrated:document.documentElement.getAttribute('data-has-hydrated'), version:document.querySelector('meta[name=docusaurus_version]')?.content, title:document.title, text:document.querySelector('main')?.innerText})\";
  console.log('After click',JSON.stringify(await evaluate(report)));
  await cdp('Page.reload');
  await waitFor(\"document.documentElement.getAttribute('data-has-hydrated')==='true' && Boolean(document.querySelector('main h1'))\");
  console.log('After reload',JSON.stringify(await evaluate(report)));
} finally {
  chrome.kill();
  await once(chrome,'exit').catch(()=>{});
  await rm(root,{recursive:true,force:true});
}
JS"

